// Reorder policy (dummy values, tune per client)
const REORDER_POINT = { "REBAR-12MM":200,"CEMENT-25KG":500,"TIMBER-50X100":300,"INSULATION-50MM":150,"BRICK-PALLET":40 };
const TARGET_LEVEL  = { "REBAR-12MM":600,"CEMENT-25KG":1500,"TIMBER-50X100":900,"INSULATION-50MM":450,"BRICK-PALLET":120 };

const whId       = r => (r.warehouse_id ?? r.ID ?? null);
const stockQty   = r => (r.stock_qty ?? r.qty);
const leadDays   = r => (r.lead_time_days ?? r.lead_time);
const supplierOf = r => ((r["supplier "] ?? r.supplier ?? "Unknown").toString().trim());

const rows = $input.all().map(i => i.json);
const poRows       = rows.filter(r => ('po_id' in r));
const movementRows = rows.filter(r => !('po_id' in r) && (('delta' in r) || ('type' in r && 'ts' in r)));
const stockRows    = rows.filter(r => !('po_id' in r) && !('delta' in r) && (("warehouse_id" in r) || ("ID" in r) || ("stock_qty" in r) || ("qty" in r)));
const leadRows     = rows.filter(r => !('po_id' in r) && !('delta' in r) && (("lead_time_days" in r) || ("lead_time" in r)) && !("warehouse_id" in r) && !("stock_qty" in r) && !("ID" in r));

function buildOnHand(sRows,mRows){
  const num=v=>(v===''||v==null||String(v).toLowerCase()==='n/a')?null:Number(v);
  const K=(w,s)=>w+'|'+s; const anchor={};
  for(const r of sRows){const w=r.warehouse_id??r.ID,s=r.sku;if(w==null||s==null)continue;anchor[K(w,s)]={qty:num(r.stock_qty??r.qty),lu:(r.last_updated||'')};}
  const delta={};
  for(const m of mRows){const w=m.warehouse_id,s=m.sku;if(w==null||s==null)continue;const k=K(w,s);const cut=anchor[k]?anchor[k].lu:'';if(String(m.ts||'')>cut)delta[k]=(delta[k]||0)+Number(m.delta||0);}
  return {get(w,s){const k=K(w,s),a=anchor[k],d=delta[k]||0;if(!a)return null;return a.qty==null?null:a.qty+d;}};
}
const oh = buildOnHand(stockRows, movementRows);

const leadBySku = {};
for (const r of leadRows) {
  const raw = leadDays(r);
  const lt = (raw === "" || raw === null || raw === undefined) ? null : Number(raw);
  const existing = leadBySku[r.sku];
  if (!existing || (lt !== null && (existing.lead_time === null || lt < existing.lead_time))) {
    leadBySku[r.sku] = { supplier: supplierOf(r), lead_time: lt };
  }
}

// open POs (not yet received) suppress re-nagging & re-proposing, keyed warehouse|sku
const OPEN = new Set(['PENDING','PLACED','CONFIRMED']);
const openBy = {};
for (const p of poRows) {
  const st = String(p.status || '').toUpperCase();
  if (!OPEN.has(st)) continue;
  const k = (p.warehouse_id ?? '') + '|' + p.sku;
  if (!openBy[k]) openBy[k] = { po_id: p.po_id, status: st, expected_date: p.expected_date || '' };
}

const flagged = [];
const pos = [];
const now = new Date().toISOString();

for (const r of stockRows) {
  const sku = r.sku;
  const rp = REORDER_POINT[sku];
  if (rp === undefined) continue;
  const wh = whId(r);
  const qty = oh.get(wh, sku);   // DERIVED on-hand

  let status, orderQty;
  if (qty === null || isNaN(qty)) { status = "UNKNOWN"; orderQty = null; }
  else if (qty <= rp) { status = (qty <= 0) ? "STOCKOUT" : "LOW"; const target = TARGET_LEVEL[sku] || rp * 3; orderQty = Math.max(target - qty, 0); }
  else continue;

  const lead = leadBySku[sku] || { supplier: "Unknown", lead_time: null };
  const k = (wh ?? '') + '|' + sku;
  const open = openBy[k] || null;

  const item = {
    warehouse: wh, sku, on_hand: qty, reorder_point: rp, status,
    suggested_order_qty: orderQty, supplier: lead.supplier, lead_time_days: lead.lead_time,
    conflict: r.conflict === true || String(r.conflict).toLowerCase() === "true",
    on_order: !!open, po_created: null
  };

  if (!open && status !== "UNKNOWN" && orderQty > 0) {
    const poId = 'PO-' + now.slice(0,10).replace(/-/g,'') + '-' + Math.random().toString(36).slice(2,6).toUpperCase();
    pos.push({
      po_id: poId, created_at: now, sku, qty: orderQty, warehouse_id: wh,
      supplier: lead.supplier, source: 'reorder', linked_order_id: '',
      lead_time_days: (lead.lead_time ?? ''), buffer_days: 3,
      placed_at: '', expected_date: '', status: 'PENDING', received_at: '', movement_posted: '', note: 'auto reorder'
    });
    item.po_created = poId;
  }
  item._po = open;
  flagged.push(item);
}

if (flagged.length === 0) return [];

const rank = { "STOCKOUT": 0, "LOW": 1, "UNKNOWN": 2 };
flagged.sort((a, b) => (rank[a.status] - rank[b.status]) || String(a.warehouse).localeCompare(String(b.warehouse)));

const lines = flagged.map(f => {
  const onHand = f.on_hand === null ? "unknown" : f.on_hand;
  const leadTxt = f.lead_time_days == null ? "lead n/a" : `${f.lead_time_days}d lead`;
  const conflictTxt = f.conflict ? "  :warning: conflict" : "";
  if (f.on_order) {
    const eta = f._po && f._po.expected_date ? `ETA ${f._po.expected_date}` : "awaiting placement";
    return `:hourglass_flowing_sand: *${f.sku}* @ ${f.warehouse} — on hand: ${onHand} — on order (${f._po.po_id}, ${eta})${conflictTxt}`;
  }
  if (f.status === "UNKNOWN") {
    return `:white_circle: *${f.sku}* @ ${f.warehouse} — on hand: unknown (reorder ≤ ${f.reorder_point}) → verify stock manually${conflictTxt}`;
  }
  const icon = f.status === "STOCKOUT" ? ":red_circle:" : ":large_orange_circle:";
  return `${icon} *${f.sku}* @ ${f.warehouse} — on hand: ${onHand} (reorder ≤ ${f.reorder_point}) → *PO proposed: ${f.suggested_order_qty}* from ${f.supplier} (${leadTxt})${conflictTxt}`;
});

const counts = flagged.reduce((a, f) => { a[f.status] = (a[f.status] || 0) + 1; return a; }, {});
const onOrderCount = flagged.filter(f => f.on_order).length;
const header = `:package: *Low-stock reorder* — ${flagged.length} flagged ` +
  `(${counts.STOCKOUT || 0} stockout, ${counts.LOW || 0} low, ${counts.UNKNOWN || 0} unknown; ` +
  `${onOrderCount} already on order, ${pos.length} new PO${pos.length === 1 ? '' : 's'} proposed)`;

const message = `${header}\n\n${lines.join("\n")}`;
return [{ json: { alert_count: flagged.length, message, items: flagged, pos } }];
